<script>
document.addEventListener("DOMContentLoaded", function () {
    const tabsMenu = document.querySelector(".tabs__menu");
    const tabsContent = document.querySelectorAll(".tabs__pane");

    tabsContent.forEach((pane, index) => {
        if (!pane.querySelector(".tabs__image")) return;
        const image = pane.querySelector(".tabs__image");
        image.style.transform = "translateY(0) scale(1) rotate(0)";
        image.style.opacity = index === 0 ? "1" : "0";
        pane.style.display = index === 0 ? "block" : "none";
    });

    tabsMenu.addEventListener("click", function (e) {
        const clickedTab = e.target.closest(".tabs__link");
        if (!clickedTab || clickedTab.classList.contains("Current")) return;

        const currentTab = document.querySelector(".tabs__link.Current");
        const currentPane = Array.from(tabsContent).find((pane) =>
            pane.style.display !== "none"
        );
        const nextIndex = Array.from(tabsMenu.children).indexOf(clickedTab);
        const nextPane = tabsContent[nextIndex];

        const currentImage = currentPane.querySelector(".tabs__image");
        currentImage.style.transition = "transform 0.5s, opacity 0.5s";
        currentImage.style.transform = "translateY(100%) scale(0.7) rotate(10deg)";
        currentImage.style.opacity = "0";

        setTimeout(() => {
            // 🔥 PLAY SOUND (Synced with content switch)
            if (window.playWarholSound) window.playWarholSound('air_hover');

            currentPane.style.display = "none";

            nextPane.style.display = "block";
            const nextImage = nextPane.querySelector(".tabs__image");
            nextImage.style.transition = "transform 0.5s, opacity 0.5s";
            nextImage.style.transformOrigin = "top center";
            nextImage.style.transform = "scale(0)";
            nextImage.style.opacity = "0";

            setTimeout(() => {
                nextImage.style.transform = "scale(1)";
                nextImage.style.opacity = "1";
            }, 50);

            currentTab.classList.remove("Current");
            clickedTab.classList.add("Current");
        }, 125);
    });
});
